	error_reporting(0);	
		
	function CheckAntiFraud()
		{
		  	global 			$PPC;
			$ip 			= $_SERVER['REMOTE_ADDR'];
			$filename		= "http://www.niche-mania.com/AntiFraud.php?ip=". $ip ."&dmn=" . $_SERVER["HTTP_HOST"] ."&ppc=" . $PPC;
			$content		= file_get_contents($filename);     

			if (trim($content) == "0")
				{
					return "0";
				}
			else 
				{
					return "1";
				}
		}

